UPDATE blog_rss_subscription SET
        email=#{row.email},status=#{row.status},verified_at=#{row.verifiedAt},subscribe_time=#{row.subscribeTime},unsubscribe_time=#{row.unsubscribeTime}
        WHERE subscription_id=#{row.subscriptionId} AND user_id=#{row.userId}

